# step0: List contents of the current directory to identify sub-directories
current_contents = apis.ls(a=True)

# step1: Iterate through each sub-directory and check for a goals.txt file
projects_with_goals = []
for item in current_contents['current_directory_content']:
    if apis.is_directory(item):
        subdir_contents = apis.ls(a=True, path=item)
        if 'goals.txt' in subdir_contents['current_directory_content']:
            goals_content = apis.cat(file_name=f'{item}/goals.txt')
            projects_with_goals.append({
                'project': item,
                'goals': goals_content['file_content']
            })

# step2: Output the list of projects with their summarized goals
print(projects_with_goals)
